<?php require 'config.php'; require 'lib.php'; need_login(); track_user(); csrf_check(); if($_SERVER['REQUEST_METHOD']==='POST'&&!is_admin()){ http_response_code(403); exit(t('Du har bara läsbehörighet.','You have read-only access.')); }
$TY=['proxmox'=>'Proxmox VE','vmware'=>'VMware ESXi','hyperv'=>'Hyper-V'];
function hconn($old){ $t=$_POST['type']??''; $c=[];
 if($t==='proxmox'){ $c['port']=(int)(($_POST['pve_port']??'')?:8006); $c['token']=trim($_POST['pve_token']??''); $sec=$_POST['pve_secret']??''; $c['secret']=($sec===''||$sec==='********')?($old['secret']??''):secret_enc($sec); $c['verify']=!empty($_POST['pve_verify'])?1:0; $c['agent']=!empty($_POST['pve_agent'])?1:0; }
 elseif($t==='vmware') $c['snmp']=snmp_param_build($_POST['s_ver']??'2',$_POST,$old['snmp']??'');
 else $c['port']=(int)(($_POST['hv_port']??'')?:10050);
 return $c; }
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??''; $hid=(int)($_POST['id']??$_POST['cid']??0); $pdo=db();
 if($a==='add'&&isset($TY[$_POST['type']??''])&&trim($_POST['host']??'')!==''){ $h=trim($_POST['host']);
  $pdo->prepare('INSERT INTO servers(name,host,hv_type,hv_conn) VALUES(?,?,?,?)')->execute([trim($_POST['name']??'')?:$h,$h,$_POST['type'],json_encode(hconn([]))]); $nid=$pdo->lastInsertId();
  $pdo->prepare("INSERT INTO server_checks(server_id,source,kind,target,label) VALUES(?,'tcp','ping','','Ping')")->execute([$nid]); applog('info','config','Host added: '.$h); $_SESSION['flash']=t('Host tillagd – första avläsningen sker inom en minut.','Host added – the first reading happens within a minute.'); }
 if($a==='edit'&&trim($_POST['host']??'')!==''){ $q2=$pdo->prepare('SELECT hv_conn FROM servers WHERE id=?'); $q2->execute([$hid]); $old=json_decode((string)$q2->fetchColumn(),true)?:[]; $h=trim($_POST['host']);
  $pdo->prepare('UPDATE servers SET name=?,host=?,comment=?,hv_conn=?,hv_poll=NULL WHERE id=? AND hv_type IS NOT NULL')->execute([trim($_POST['name']??'')?:$h,$h,trim($_POST['comment']??''),json_encode(hconn($old)),$hid]); }
 if($a==='test'){ $q=$pdo->prepare('SELECT * FROM servers WHERE id=? AND hv_type IS NOT NULL'); $q->execute([$hid]); if($s=$q->fetch()){ $r=poll_host($s); $_SESSION['flash']=$r['ok']?('✔ '.$s['name'].': '.count($r['data']['vms']).' VM, '.count($r['data']['storage']).' storage'):('✖ '.$s['name'].': '.$r['error']); } }
 if($a==='toggle_dash'){ $pdo->prepare('UPDATE servers SET dash_hidden=1-dash_hidden WHERE id=? AND hv_type IS NOT NULL')->execute([$hid]); }
 if($a==='toggle'){ $pdo->prepare('UPDATE servers SET enabled=1-enabled,hv_poll=NULL WHERE id=? AND hv_type IS NOT NULL')->execute([$hid]); }
 if($a==='del'){ applog('warning','config','Host deleted, id '.$hid); $q=$pdo->prepare('SELECT id FROM server_checks WHERE server_id=?'); $q->execute([$hid]); purge_targets([$hid],array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN))); $pdo->prepare('DELETE FROM servers WHERE id=? AND hv_type IS NOT NULL')->execute([$hid]); }
 header('Location: '.((($_POST['back']??'')==='detail'&&$a!=='del')?'host.php?id='.$hid:'hosts.php'));exit; }
$ed=null; $ec=[]; if(isset($_GET['edit'])&&is_admin()){ $q=db()->prepare('SELECT * FROM servers WHERE id=? AND hv_type IS NOT NULL'); $q->execute([(int)$_GET['edit']]); $ed=$q->fetch()?:null; $ec=$ed?(json_decode((string)$ed['hv_conn'],true)?:[]):[]; }
$sp=snmp_param_parse($ed&&$ed['hv_type']==='vmware'?($ec['snmp']??''):''); $et=$ed['hv_type']??'proxmox';
function hfin($v){ return $v!==null&&$v!==''; }
top(t('Virtualisering','Virtualization')); flash(); ?>
<h2><?= t('Virtualisering','Virtualization') ?></h2>
<?php if(is_admin()): ?><form method="post" class="card inline"><?= csrf_field() ?><input type="hidden" name="a" value="<?= $ed?'edit':'add' ?>"><?php if($ed) echo '<input type="hidden" name="id" value="'.$ed['id'].'">'; ?>
<?php if($ed) echo '<input type="hidden" name="type" value="'.h($ed['hv_type']).'"><b style="align-self:center">'.h($TY[$ed['hv_type']]).'</b>'; else { ?><select name="type" id="htype"><?php foreach($TY as $k=>$n) echo '<option value="'.$k.'">'.h($n).'</option>'; ?></select><?php } ?>
<input name="name" value="<?= h($ed['name']??'') ?>" placeholder="<?= t('Namn (valfritt)','Name (optional)') ?>"><input name="host" value="<?= h($ed['host']??'') ?>" placeholder="<?= 'IP/Hostname' ?>" required>
<span class="fg" data-s="proxmox"><input name="pve_port" type="number" style="width:90px" value="<?= h($ec['port']??'') ?>" placeholder="8006"><input name="pve_token" size="26" value="<?= h($ec['token']??'') ?>" placeholder="user@pam!tokenid"><input name="pve_secret" type="password" size="26" autocomplete="new-password" onfocus="this.select()" value="<?= !empty($ec['secret'])?'********':'' ?>" placeholder="<?= t('Token-hemlighet','Token secret') ?>"><label class="chk"><input type="checkbox" name="pve_verify" value="1"<?= !empty($ec['verify'])?' checked':'' ?>> <?= t('Verifiera TLS','Verify TLS') ?></label><label class="chk" title="<?= h(t('Hämta diskanvändning per VM via QEMU guest agent (kräver agent i VM:en och rättigheten VM.GuestAgent.Audit, i äldre Proxmox VM.Monitor)','Fetch per-VM disk usage via the QEMU guest agent (requires the agent in the VM and the VM.GuestAgent.Audit privilege, VM.Monitor in older Proxmox)')) ?>"><input type="checkbox" name="pve_agent" value="1"<?= !empty($ec['agent'])?' checked':'' ?>> <?= t('Disk via guest agent','Disk via guest agent') ?></label></span>
<span class="fg" data-s="vmware"><input name="s_port" type="number" min="1" max="65535" style="width:110px" value="<?= h($sp["port"]??"") ?>" placeholder="<?= t("Port (standard 161)","Port (default 161)") ?>"> <select name="s_ver" class="sver"><option value="2"<?= $sp['ver']==='2'?' selected':'' ?>>SNMP v2c</option><option value="3"<?= $sp['ver']==='3'?' selected':'' ?>>SNMP v3 (<?= t('standardinställningar','defaults') ?>)</option></select><input class="s2f" name="s_comm" value="<?= h($sp['comm']) ?>" placeholder="<?= 'Community' ?>"><?= snmp_v3_fields($sp) ?></span>
<span class="fg" data-s="hyperv"><input name="hv_port" type="number" style="width:190px" value="<?= h($ec['port']??'') ?>" placeholder="<?= t('Agent-port (10050)','Agent port (10050)') ?>"></span>
<label class="f" style="min-width:260px"><?= $ed?t('Kommentar','Comment'):'' ?><?php if($ed): ?><textarea name="comment" rows="1" cols="30"><?= h($ed['comment']??'') ?></textarea><?php endif; ?></label>
<button class="btn"><?= $ed?t('Spara ändringar','Save changes'):t('Lägg till host','Add host') ?></button><?php if($ed) echo '<a class="btn danger" href="hosts.php">'.t('Avbryt','Cancel').'</a>'; ?></form>
<script>(function(){var s=document.getElementById('htype'),g=[].slice.call(document.querySelectorAll('.fg')),cur=<?= json_encode($et) ?>;function f(){var v=s?s.value:cur;g.forEach(function(x){var on=x.getAttribute('data-s')===v;x.style.display=on?'contents':'none';[].forEach.call(x.querySelectorAll('input,select'),function(i){i.disabled=!on})})}if(s)s.onchange=f;f()})();</script>
<?php endif; ?>
<table class="card"<?= tc_attr('hosts') ?>><tr><th data-k="name"><?= t('Namn','Name') ?></th><th data-k="type"><?= t('Typ','Type') ?></th><th data-k="addr"><?= t('Adress','Address') ?></th><th data-k="status">Status</th><th data-k="vms">VMs</th><th data-k="last"><?= t('Senaste kontroll','Last check') ?></th><?= tc_th('ver',t('Version','Version')) ?><?= tc_th('nodes',t('Noder','Nodes')) ?><?= tc_th('stopped',t('Stoppade VM','Stopped VMs')) ?><?= tc_th('cpu','CPU') ?><?= tc_th('mem',t('Minne','Memory')) ?><?= tc_th('stor',t('Fullaste lagring','Fullest storage')) ?><?= tc_th('nst',t('Lagringsvolymer','Storage volumes')) ?><?= tc_th('upt','Uptime') ?><?= tc_th('cmt',t('Kommentar','Comment')) ?><?= tc_th('grp',t('Grupper','Groups')) ?><?= dg_ths() ?><th></th></tr>
<?php foreach(db()->query('SELECT *,TIMESTAMPDIFF(SECOND,hv_poll,NOW()) AS age FROM servers WHERE hv_type IS NOT NULL ORDER BY name') as $s): $d=json_decode((string)$s['hv_data'],true)?:[]; $vs=$d['vms']??[]; $run=count(array_filter($vs,fn($x)=>in_array($x['state']??'',['running','poweredon'],true))); $en=(int)$s['enabled']===1; ?>
<tr class="<?= $en?'':'dim' ?>" data-href="host.php?id=<?= $s['id'] ?>"><td><b class="rn"><?= h($s['name']) ?></b><?= $en?'':' <small>('.t('inaktiverad','disabled').')</small>' ?><?= !empty($s['dash_hidden'])?' <small>('.t('dold på dash','hidden on dash').')</small>':'' ?><?= hfin($s['comment'])?'<br><small class="mut">'.h($s['comment']).'</small>':'' ?></td><td><?= h($TY[$s['hv_type']]??$s['hv_type']) ?><?= !empty($d['version'])?' <small class="mut">'.h($d['version']).'</small>':'' ?></td><td><?= h($s['host']) ?></td>
<td class="det <?= $s['hv_status']==='up'?'okt':($s['hv_status']?'badt':'') ?>"><?= $s['hv_status']?h($s['hv_status']).($s['hv_error']?' – '.h($s['hv_error']):''):t('väntar','pending') ?></td><td><?= $vs?$run.' / '.count($vs):'–' ?></td><td><?= $s['age']===null?'–':($s['age']<60?$s['age'].' s':floor($s['age']/60).' min') ?></td>
<?php $nd=$d['nodes']??[]; $nc=count($nd); $cp=$nc?array_sum(array_map(fn($x)=>(float)($x['cpu']??0),$nd))/$nc:null; $mu=array_sum(array_map(fn($x)=>(float)($x['mem']??0),$nd)); $mt=array_sum(array_map(fn($x)=>(float)($x['mem_t']??0),$nd)); $mp=$mt>0?round($mu/$mt*100,1):(isset($d['mem'])?$d['mem']:null); if($cp===null&&isset($d['cpu'])) $cp=$d['cpu'];
 $fs=null; $fp=-1; foreach($d['storage']??[] as $x){ if(($x['total']??0)>0){ $pp=round($x['used']/$x['total']*100); if($pp>$fp){ $fp=$pp; $fs=$x['n'].' '.$pp.'%'; } } } $ups=array_filter(array_map(fn($x)=>(int)($x['up']??0),$nd)); $um=$ups?min($ups):0;
 echo tc_td($d['version']??null),tc_td($nc?(string)$nc:null),tc_td($vs?(string)(count($vs)-$run):null),bar_cell($cp,'cpu'),bar_cell($mp,'mem'),tc_td($fs,$fp>=0?$fp:null),tc_td(!empty($d['storage'])?(string)count($d['storage']):null),tc_td($um?tc_upt($um):null,$um),tc_td($s['comment']??null); ?>
<?= dg_td($s['id']) ?><?= dg_tds($s['id']) ?><td class="inline"><?php if(is_admin()): ?><a class="btn sm" href="hosts.php?edit=<?= $s['id'] ?>"><?= t('Ändra','Edit') ?></a><?= fbtn('toggle',$s['id'],$en?t('Inaktivera','Disable'):t('Aktivera','Enable'),$en?'warn':'go') ?><?= fbtn('del',$s['id'],t('Ta bort','Delete'),'danger',t('Ta bort hosten och all dess data?','Delete the host and all its data?')) ?><?php endif; ?></td></tr>
<?php endforeach; ?></table>
